"""Registration helpers for experimental CLI commands."""

from __future__ import annotations

from ..judge_training.icon_reuse import STAGING_ROUTES


def register_judge_command(subparsers) -> None:
    judge = subparsers.add_parser("judge", help="Register and evaluate trained Judge checkpoints.")
    actions = judge.add_subparsers(dest="judge_action", required=True)
    register = actions.add_parser("register", help="Register a checkpoint manifest without loading weights.")
    register.add_argument("--checkpoint", required=True)
    register.add_argument("--manifest", required=True, help="JSON manifest containing model_id, dataset_version, roles, and git_commit.")
    register.add_argument("--registry", required=True)
    register.add_argument("--json", action="store_true")
    evaluate = actions.add_parser("evaluate", help="Evaluate recorded predictions on a fixed dataset.")
    evaluate.add_argument("--checkpoint")
    evaluate.add_argument("--dataset", required=True)
    evaluate.add_argument("--predictions", required=True)
    evaluate.add_argument("--suite", default="hidden_test")
    evaluate.add_argument("--suite-manifest", help="Frozen suite manifest JSON.")
    evaluate.add_argument("--report-out", help="Directory for JSON and Markdown evaluation reports.")
    evaluate.add_argument("--strict-gates", action="store_true", help="Return a failing command status when evaluation gates fail.")
    evaluate.add_argument("--json", action="store_true")
    shadow = actions.add_parser("shadow", help="Compare trained predictions with Bootstrap predictions.")
    shadow.add_argument("--checkpoint")
    shadow.add_argument("--dataset", required=True)
    shadow.add_argument("--predictions", required=True, help="Trained Judge prediction JSONL.")
    shadow.add_argument("--bootstrap-predictions", required=True)
    shadow.add_argument("--suite-manifest", help="Frozen suite manifest JSON.")
    shadow.add_argument("--report-out", help="Directory for JSON and Markdown shadow reports.")
    shadow.add_argument("--strict-gates", action="store_true", help="Return a failing command status when trained gates fail.")
    shadow.add_argument("--json", action="store_true")
    baseline = actions.add_parser("baseline", help="Run the resumable Bootstrap VLM baseline on validation data.")
    baseline.add_argument("--dataset", required=True)
    baseline.add_argument("--out", required=True)
    baseline.add_argument("--limit", type=int)
    baseline.add_argument("--model")
    baseline.add_argument("--timeout", type=int, default=180)
    baseline.add_argument("--retries", type=int, default=2)
    baseline.add_argument("--json", action="store_true")
    train = actions.add_parser("train", help="Run the multi-image DPO loop over Judge preference pairs.")
    train.add_argument("--dataset", required=True, help="DPO export JSONL or the directory that holds it.")
    train.add_argument("--out", required=True, help="Run directory for checkpoints, metrics and the version lock.")
    train.add_argument("--config", help="Training config JSON; explicit flags override it.")
    train.add_argument("--backend", choices=("transformers", "synthetic"))
    train.add_argument("--base-model")
    train.add_argument("--beta", type=float)
    train.add_argument("--learning-rate", type=float)
    train.add_argument("--epochs", type=int)
    train.add_argument("--gradient-accumulation", type=int)
    train.add_argument("--max-length", type=int)
    train.add_argument("--image-max-pixels", type=int, help="Cap the vision encoder's longest edge in pixels; 0 keeps the processor default.")
    train.add_argument("--lora-r", type=int)
    train.add_argument("--lora-alpha", type=int)
    train.add_argument("--lora-dropout", type=float)
    train.add_argument("--no-4bit", action="store_false", dest="load_in_4bit", default=None, help="Load the base model without 4-bit quantisation.")
    train.add_argument("--gradient-checkpointing", action="store_true", dest="gradient_checkpointing", default=None, help="Trade compute for memory: recompute activations and pin the model to the first GPU.")
    train.add_argument("--shard-across-gpus", action="store_true", dest="shard_across_gpus", default=None, help="Spread the layers over every visible GPU; needed for a backbone that does not fit on one card.")
    train.add_argument("--seed", type=int)
    train.add_argument("--max-steps", type=int)
    train.add_argument("--save-every", type=int)
    train.add_argument("--validation-dataset", help="Held-out DPO JSONL scored at every checkpoint; its score decides which checkpoint is the trained one.")
    train.add_argument("--eval-limit", type=int, help="Score only the first N held-out pairs per checkpoint; 0 scores all of them.")
    train.add_argument("--early-stop-margin", type=float, help="Stop once the median held-out margin reaches this; 0 trains the whole schedule.")
    train.add_argument("--objective", choices=("dpo", "sft"), help="dpo ranks chosen/rejected completions; sft fits the chosen JSON only.")
    train.add_argument("--generate-eval-limit", type=int, help="Generate on the first N held-out pairs per checkpoint and select by that pairwise; 0 skips it.")
    train.add_argument("--selection", choices=("ranking", "generate", "choice"), help="choice scores short figure and defect answers; ranking and generate keep the older selectors.")
    train.add_argument("--resume-from", help="Checkpoint directory of the run to continue.")
    train.add_argument("--init-from", help="Load this checkpoint's weights, then start step 0 and recompute the reference on those weights.")
    train.add_argument("--json", action="store_true")
    score_choice = actions.add_parser("score-choice", help="Score a base model or checkpoint on two-field choice items.")
    score_choice.add_argument("--dataset", required=True, help="Choice JSONL to score.")
    score_choice.add_argument("--out", required=True, help="JSON report path.")
    score_choice.add_argument("--base-model", required=True)
    score_choice.add_argument("--config", help="Training config used for the vision budget and 4-bit load.")
    score_choice.add_argument("--checkpoint", default="", help="Checkpoint directory to load before scoring. Empty scores the base model.")
    score_choice.add_argument("--predictions-out", default="", help="Write one JSONL row per scored side, so the choice gate can read the same run.")
    score_choice.add_argument("--json", action="store_true")
    gate_choice = actions.add_parser("gate-choice", help="Gate a choice checkpoint on its scored predictions and decide promotion.")
    gate_choice.add_argument("--predictions", required=True, help="Choice predictions JSONL written by score-choice --predictions-out.")
    gate_choice.add_argument("--dataset", default="", help="Exam the predictions came from, for the report header.")
    gate_choice.add_argument("--checkpoint", default="", help="Checkpoint the predictions came from.")
    gate_choice.add_argument("--model-id", default="", help="Model id the registry manifest should carry.")
    gate_choice.add_argument("--dataset-version", default="", help="Dataset version the registry manifest should carry.")
    gate_choice.add_argument("--git-commit", default="", help="Git commit the registry manifest should carry.")
    gate_choice.add_argument("--threshold", action="append", default=[], metavar="NAME=VALUE", help="Override one gate threshold; repeatable.")
    gate_choice.add_argument("--report-out", help="Directory for the JSON and Markdown gate reports.")
    gate_choice.add_argument("--strict-gates", action="store_true", help="Return a failing command status when a gate fails.")
    gate_choice.add_argument("--json", action="store_true")
    promote = actions.add_parser("promote", help="Gate each defect class, run the adversarial checklist and decide promotion.")
    promote.add_argument("--dataset", required=True, help="Frozen suite JSONL the checkpoint was judged on.")
    promote.add_argument("--predictions", required=True, help="Judge prediction JSONL for this checkpoint.")
    promote.add_argument("--suite", default="hidden_test", help="Suite name; hidden_test by default.")
    promote.add_argument("--suite-manifest", help="Frozen suite manifest JSON.")
    promote.add_argument("--checkpoint", help="Checkpoint the predictions came from.")
    promote.add_argument("--baseline-predictions", help="Bootstrap VLM baseline predictions on the same suite.")
    promote.add_argument("--bootstrap-predictions", help="Bootstrap predictions used for the shadow comparison.")
    promote.add_argument("--training-report", help="training_report.json of the run behind this checkpoint.")
    promote.add_argument("--class-threshold", type=float, help="Recall threshold applied to each gating defect class; 0.9 by default.")
    promote.add_argument("--adversarial-threshold", type=float, default=0.9, help="Pass rate the adversarial checklist has to reach.")
    promote.add_argument("--report-out", help="Directory for the JSON and Markdown promotion reports.")
    promote.add_argument("--strict-gates", action="store_true", help="Return a failing command status when a gate fails.")
    promote.add_argument("--json", action="store_true")
    bakeoff = actions.add_parser("bakeoff", help="Compare a fixed smoke subset across candidate VLM backbones.")
    bakeoff.add_argument("--dataset", required=True)
    bakeoff.add_argument("--out", required=True)
    bakeoff.add_argument("--model", action="append", dest="models")
    bakeoff.add_argument("--limit", type=int, default=40)
    bakeoff.add_argument("--timeout", type=int, default=180)
    bakeoff.add_argument("--retries", type=int, default=2)
    bakeoff.add_argument("--json", action="store_true")
    sweep = actions.add_parser("sweep-memory", help="Quarantine Memory an older Judge measured and re-measure it.")
    sweep.add_argument("--experience-library", required=True, help="Experience library whose Memory should be swept.")
    sweep.add_argument("--judge-model", default="", help="Model name of the Judge that is now in charge.")
    sweep.add_argument("--judge-mode", default="trained", help="Judge mode the incoming Judge runs in.")
    sweep.add_argument("--judge-role", default="frozen", help="Judge role the incoming Judge serves.")
    sweep.add_argument("--bootstrap-judge", action="store_true", help="Treat the incoming Judge as the untrained bootstrap one.")
    sweep.add_argument("--selection", choices=("mismatched", "bootstrap", "all"), default="mismatched", help="Which rows stop being injected: another Judge's measurements (default), the untrained Judge's, or all of them.")
    sweep.add_argument("--registry", default="", help="Checkpoint registry to resolve --model-id against.")
    sweep.add_argument("--model-id", default="", help="Registered Judge model id to sweep against; overrides --judge-model.")
    sweep.add_argument("--apply", action="store_true", help="Write the quarantine; without it the sweep only reports what it would do.")
    sweep.add_argument("--revalidate", action="store_true", help="Re-measure the quarantined rows with the paired ON/OFF harness.")
    sweep.add_argument("--limit", type=int, default=0, help="Re-measure at most this many rows in this pass; 0 means all.")
    sweep.add_argument("--out", default="output/judge_memory_sweep", help="Directory for the sweep report.")
    sweep.add_argument("--json", action="store_true")
    handover = actions.add_parser("handover", help="Drive train, predict, promote, register and the Memory sweep as one chain.")
    handover.add_argument("--dataset", default="", help="DPO export the Judge trains on; a frozen suite manifest may name it instead.")
    handover.add_argument("--suite-manifest", default="", help="Frozen suite manifest the checkpoint is gated on.")
    handover.add_argument("--model-id", default="", help="Model id the Judge is registered under.")
    handover.add_argument("--dataset-version", default="", help="Dataset version the checkpoint was trained on; the suite manifest names it by default.")
    handover.add_argument("--registry", default="", help="Checkpoint registry to register the Judge in.")
    handover.add_argument("--out", required=True, help="Directory the chain's artifacts and report live in.")
    handover.add_argument("--checkpoint", default="", help="Checkpoint to hand over; the last one the training saved by default.")
    handover.add_argument("--training-report", default="", help="Existing training_report.json to reuse instead of training.")
    handover.add_argument("--predict-from", default="", help="Predicted rows to reuse instead of running a batch.")
    handover.add_argument("--bootstrap-predictions", default="", help="Bootstrap predictions the shadow comparison holds the checkpoint against.")
    handover.add_argument("--no-shadow", action="store_true", help="Gate without the shadow comparison, which keeps the checkpoint off the frozen role.")
    handover.add_argument("--allow-experimental", action="store_true", help="Register a checkpoint the gate did not approve, for experiments only.")
    handover.add_argument("--judge-mode", choices=("trained", "vlm", "heuristic"), default="trained", help="Mode the incoming Judge runs in.")
    handover.add_argument("--judge-model", default="", help="Model name of the Judge that is now in charge.")
    handover.add_argument("--backend", choices=("synthetic", "transformers"), default="synthetic", help="Training backend; synthetic runs on this machine.")
    handover.add_argument("--experience-library", default="", help="Experience library whose Memory is re-measured against the incoming Judge.")
    handover.add_argument("--sweep-selection", choices=("mismatched", "bootstrap", "all"), default="mismatched", help="Which rows stop being injected.")
    handover.add_argument("--sweep-limit", type=int, default=0, help="Re-measure at most this many rows; 0 means all.")
    handover.add_argument("--git-commit", default="", help="Commit the Judge was trained from; HEAD is read by default.")
    handover.add_argument("--force", action="store_true", help="Re-run steps whose artifacts are already on disk.")
    handover.add_argument("--dry-run", action="store_true", help="Plan the chain without running or writing anything.")
    handover.add_argument("--json", action="store_true")


def register_judge_data_commands(subparsers) -> None:
    parser = subparsers.add_parser("judge-data", help="Build or validate Shadow-ready Judge training JSONL data.")
    actions = parser.add_subparsers(dest="judge_data_action", required=True)
    build = actions.add_parser("build", help="Build outcome, repair, and trajectory records from direct evolution runs.")
    build.add_argument("--runs", required=True, help="Run directory or root containing direct evolution process artifacts.")
    build.add_argument("--out", required=True, help="Dataset directory or .jsonl output path.")
    build.add_argument("--dataset-version", default="judge-dataset-v003")
    build.add_argument("--json", action="store_true", help="Emit JSON.")
    validate = actions.add_parser("validate", help="Validate a JudgeExample JSONL file or dataset directory.")
    validate.add_argument("--dataset", required=True, help="Dataset directory or JSONL path.")
    validate.add_argument("--json", action="store_true", help="Emit JSON.")
    audit = actions.add_parser("audit", help="Count what a built Judge dataset holds and what it is still missing.")
    audit.add_argument("--dataset", required=True, help="Dataset directory holding judge_examples.jsonl and preference_pairs.jsonl.")
    audit.add_argument("--out", help="Directory for audit.json and audit.md; the dataset directory by default.")
    audit.add_argument("--strict", action="store_true", help="Report a failing status when a required quota is unmet.")
    audit.add_argument("--json", action="store_true", help="Emit JSON.")
    negative = actions.add_parser("controlled-negatives", help="Synthesise measured rollback rounds from existing run candidates.")
    negative.add_argument("--runs", required=True, help="Run directory or root containing direct evolution process artifacts.")
    negative.add_argument("--out", required=True, help="Runs root for the synthesised rounds; feed it to judge-data build.")
    negative.add_argument("--round", type=int, help="Source round index; defaults to every round that compiled a candidate.")
    negative.add_argument("--scripts", nargs="+", help="Subset of out-of-budget scripts to run; defaults to all.")
    negative.add_argument("--split", help="Frozen split ledger; hidden_test and exploration papers are skipped.")
    negative.add_argument("--limit", type=int, default=0, help="Maximum synthesised rounds; 0 means all.")
    negative.add_argument("--json", action="store_true", help="Emit JSON.")
    split = actions.add_parser("split", help="Assign every paper of a frozen snapshot to train, validation or hidden_test.")
    split.add_argument("--snapshot", required=True, help="Frozen source snapshot directory; opened read-only.")
    split.add_argument("--out", required=True, help="Split version directory to create; refuses to overwrite a sealed version.")
    split.add_argument("--split-id", help="Split version id; defaults to the default seed.")
    split.add_argument("--seed", help="Stable hash bucket seed; defaults to the split id.")
    split.add_argument("--ratios", default="65/15/20", help="train/validation/hidden target ratios.")
    split.add_argument("--perceptual-hash-report", help="Passing perceptual hash report; COMPLETE is only written when it is given.")
    split.add_argument("--json", action="store_true", help="Emit JSON.")
    check_split = actions.add_parser("validate-split", help="Re-derive a written split version and check it against its manifest.")
    check_split.add_argument("--split", required=True, help="Split version directory.")
    check_split.add_argument("--json", action="store_true", help="Emit JSON.")
    pilot = actions.add_parser("select-pilot", help="Select the Pilot set from the train and validation splits only.")
    pilot.add_argument("--split", required=True, help="Sealed split version directory.")
    pilot.add_argument("--snapshot", required=True, help="Frozen source snapshot directory; opened read-only.")
    pilot.add_argument("--out", required=True, help="Pilot version directory to create.")
    pilot.add_argument("--pilot-id", help="Pilot version id; defaults to the default pilot id.")
    pilot.add_argument("--seed", help="Stable selection seed; defaults to the pilot id.")
    pilot.add_argument("--labels", help="Label cache JSONL; defaults to a sibling _labels directory.")
    pilot.add_argument("--work-dir", help="Rendered candidate directory; defaults to a sibling _work directory.")
    pilot.add_argument("--workers", type=int, default=4, help="Concurrent labelling requests.")
    pilot.add_argument("--dpi", type=int, default=150, help="Render resolution used for labelling.")
    pilot.add_argument("--pool-multiplier", type=int, default=3, help="Candidates per Pilot slot.")
    pilot.add_argument("--no-vlm", action="store_true", help="Skip the vision model and label from captions only.")
    pilot.add_argument("--structure-gate", help="Second-pass gate cache JSONL; defaults to a sibling _labels directory.")
    pilot.add_argument("--no-structure-gate", action="store_true", help="Skip the second-pass schematic check.")
    pilot.add_argument("--json", action="store_true", help="Emit JSON.")
    check_pilot = actions.add_parser("validate-pilot", help="Re-read a written Pilot version and check it.")
    check_pilot.add_argument("--pilot", required=True, help="Pilot version directory.")
    check_pilot.add_argument("--json", action="store_true", help="Emit JSON.")
    build_graphs = actions.add_parser("build-pilot-graphs", help="Prepare or build the Phase 3 Pilot graph artifacts from a frozen snapshot.")
    build_graphs.add_argument("--snapshot", required=True, help="Frozen source snapshot directory; opened read-only.")
    build_graphs.add_argument("--pilot", required=True, help="Sealed Pilot version directory; opened read-only.")
    build_graphs.add_argument("--out", required=True, help="Pilot graph version directory to create; refuses to overwrite a sealed version.")
    build_graphs.add_argument("--graph-id", help="Graph version id; defaults to the default graph id.")
    build_graphs.add_argument("--stages", default="prepare", help="Comma separated stages: prepare, review, contract, graph, visual, bind, index, check.")
    build_graphs.add_argument("--limit", type=int, help="Only prepare the first N Pilot papers.")
    build_graphs.add_argument("--model", help="Provider model used by the review stage.")
    build_graphs.add_argument("--timeout", type=int, default=300, help="Provider timeout per review or contract call.")
    build_graphs.add_argument("--retries", type=int, default=1, help="Provider retries per review or contract call.")
    build_graphs.add_argument("--workers", type=int, default=4, help="Concurrent provider calls.")
    build_graphs.add_argument("--figure-dpi", type=int, default=150, help="Render resolution used before the framework figure is read; 72 to 400.")
    build_graphs.add_argument("--max-long-side", type=int, default=1600, help="Longest side of the rendered figure that is sent to the provider.")
    build_graphs.add_argument("--probe-top-k", type=int, default=5, help="Structurally closest cases reported per retrieval probe query.")
    build_graphs.add_argument("--probe-limit", type=int, default=64, help="Number of papers the retrieval probe queries; 0 probes every paper.")
    build_graphs.add_argument("--embedding-model", default="", help="Encoder the index stage stores one vector per record and per subgraph with; the offline hashing encoder by default, or st:<local model directory> for a pinned local sentence-transformers model.")
    build_graphs.add_argument("--resume", action="store_true", help="Reuse the stored artifacts of this version and only run the missing work.")
    build_graphs.add_argument("--strict-review", action="store_true", help="Treat review and contract coverage warnings as failures.")
    build_graphs.add_argument("--json", action="store_true", help="Emit JSON.")
    check_graphs = actions.add_parser("validate-pilot-graphs", help="Re-read a written Pilot graph version and check it.")
    check_graphs.add_argument("--graphs", required=True, help="Pilot graph version directory.")
    check_graphs.add_argument("--json", action="store_true", help="Emit JSON.")
    export_contracts = actions.add_parser(
        "export-contracts",
        help="Write a middleware version's per paper contracts where the generation line reads them.",
    )
    export_contracts.add_argument("--graphs", required=True, help="Middleware graph version directory; opened read-only.")
    export_contracts.add_argument("--out", required=True, help="Output root to create: one directory per paper.")
    export_contracts.add_argument("--snapshot", help="Frozen snapshot the version was built from; defaults to the one its manifest names.")
    export_contracts.add_argument("--paper", action="append", dest="papers", default=[], help="Export only this paper id; repeatable.")
    export_contracts.add_argument("--limit", type=int, help="Export only the first N papers.")
    export_contracts.add_argument("--json", action="store_true", help="Emit JSON.")
    icon_reuse = actions.add_parser(
        "map-icon-reuse",
        help="Map the sealed middleware contract's icon slots onto the icons a paper's legacy run already owns.",
    )
    icon_reuse.add_argument("--contracts", required=True, help="Exported middleware contract root: one directory per paper.")
    icon_reuse.add_argument("--legacy-root", required=True, help="Runs root that holds each paper's legacy run.")
    icon_reuse.add_argument("--out", required=True, help="Directory for mapping.jsonl, the contact sheets and the coverage report.")
    icon_reuse.add_argument("--legacy-attempt", default="attempt_01", help="Attempt directory name inside each legacy run.")
    icon_reuse.add_argument("--limit", type=int, default=0, help="Read only the first N papers; 0 means all.")
    icon_reuse.add_argument("--adjudicate", action="store_true", help="Let the VLM keep, drop or replace every lexical proposal and re-tier the ones it confirms; one text call per paper.")
    icon_reuse.add_argument("--model", help="Model for the adjudication call; defaults to RFS_ICON_REUSE_MODEL.")
    icon_reuse.add_argument("--timeout", type=int, default=180, help="Per call timeout in seconds.")
    icon_reuse.add_argument("--retries", type=int, default=1, help="Retries per adjudication call.")
    icon_reuse.add_argument("--workers", type=int, default=1, help="Papers adjudicated in parallel; adjudication is one slow call per paper.")
    icon_reuse.add_argument("--stage-into", help="Batch root to copy the reusable icons into, where a fresh run reuses them instead of paying the provider.")
    icon_reuse.add_argument("--round-index", type=int, default=0, help="Round directory number the fresh run draws first.")
    icon_reuse.add_argument("--candidate", default="candidate_00", help="Candidate directory name the fresh run draws first.")
    icon_reuse.add_argument("--json", action="store_true", help="Emit JSON.")
    stage_reuse = actions.add_parser(
        "stage-icon-reuse",
        help="Pre-stage the icons a mapping table already certified, without paying the model again.",
    )
    stage_reuse.add_argument("--mapping", required=True, help="mapping.jsonl written by map-icon-reuse.")
    stage_reuse.add_argument("--stage-into", required=True, help="Batch root whose runs will read the icons.")
    stage_reuse.add_argument("--routes", default=",".join(STAGING_ROUTES), help="Mapping routes whose PNGs may be staged.")
    stage_reuse.add_argument("--attempt", default="attempt_01", help="Attempt directory name inside each fresh run.")
    stage_reuse.add_argument("--round-index", type=int, default=0, help="Round directory number the fresh run draws first.")
    stage_reuse.add_argument("--candidate", default="candidate_00", help="Candidate directory name the fresh run draws first.")
    stage_reuse.add_argument("--force", action="store_true", help="Overwrite a PNG that is already staged.")
    stage_reuse.add_argument("--dry-run", action="store_true", help="Report the plan without writing anything.")
    stage_reuse.add_argument("--json", action="store_true", help="Emit JSON.")
    contract_subset = actions.add_parser(
        "build-contract-subset",
        help="Seal the papers that carry a middleware contract and an earlier run to reuse icons from.",
    )
    contract_subset.add_argument("--snapshot", required=True, help="Frozen source snapshot directory; opened read-only.")
    contract_subset.add_argument("--contracts", required=True, help="Exported middleware contract root: one directory per paper.")
    contract_subset.add_argument("--legacy-root", required=True, help="Runs root holding each paper's earlier run.")
    contract_subset.add_argument("--out", required=True, help="Subset version directory to create.")
    contract_subset.add_argument("--subset-id", required=True, help="Subset version id; also the batch id a wave reports under.")
    contract_subset.add_argument("--split", help="Frozen split version whose labels the subset carries.")
    contract_subset.add_argument("--names-out", help="Write the selected paper directory names here, one per line.")
    contract_subset.add_argument("--exclude-drawn", action="append", default=[], help="Batch root whose delivered papers are dropped; repeatable.")
    contract_subset.add_argument("--mapping", help="Reuse mapping table, when the reusable slot counts should be reported.")
    contract_subset.add_argument("--legacy-attempt", default="attempt_01", help="Attempt directory name inside each earlier run.")
    contract_subset.add_argument("--limit", type=int, default=0, help="Keep only the first N papers; 0 means all.")
    contract_subset.add_argument("--allow-no-reusable-icon", action="store_true", dest="allow_no_reusable_icon", help="Also keep a paper whose earlier run owns no icon the re-draw may reuse; it then pays for every icon.")
    contract_subset.add_argument("--json", action="store_true", help="Emit JSON.")
    perceptual = actions.add_parser("perceptual-hash", help="Render every figure of a snapshot and record its perceptual hash.")
    perceptual.add_argument("--snapshot", required=True, help="Frozen source snapshot directory; opened read-only.")
    perceptual.add_argument("--out", required=True, help="Perceptual hash report path to write.")
    perceptual.add_argument("--dpi", type=int, default=72, help="Render resolution used before hashing.")
    perceptual.add_argument("--workers", type=int, default=8, help="Number of render processes.")
    perceptual.add_argument("--near-distance", type=int, default=4, help="Hamming distance counted as near duplicate.")
    perceptual.add_argument("--json", action="store_true", help="Emit JSON.")
    freeze = actions.add_parser("freeze-suite", help="Create a content-addressed Judge evaluation suite manifest.")
